import Foundation
import Testing

@testable import NetMicProtocol

/// shared/test_vectors.txt, generated by scripts/gen-test-vectors.py. The C++
/// suite (driver/tests/test_protocol.cpp) checks the same file.
private let vectorLines: [[String]] = {
    let url = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
        .deletingLastPathComponent().appendingPathComponent("shared/test_vectors.txt")
    let text = try! String(contentsOf: url, encoding: .utf8)
    return text.split(separator: "\n").map { $0.split(separator: " ").map(String.init) }
        .filter { !$0.isEmpty && $0[0] != "#" }
}()

private func hex(_ s: String) -> [UInt8] { s == "-" ? [] : parseHex(s)! }

private func vectors(_ kind: String) -> [[String]] { vectorLines.filter { $0[0] == kind } }

@Suite struct ProtocolVectorTests {
    @Test func vectorFileLoaded() {
        #expect(vectors("valid").count >= 8)
        #expect(vectors("invalid").count >= 10)
    }

    @Test func encodeMatchesVectors() {
        for v in vectors("valid") {
            let header = PacketHeader(type: PacketType(rawValue: UInt8(v[2])!)!, seq: UInt32(v[3])!,
                                      streamId: UInt32(v[4])!, samplePos: UInt64(v[5])!)
            #expect(Packet.encode(header, payload: hex(v[6])) == hex(v[7]), "\(v[1])")
        }
    }

    @Test func decodeMatchesVectors() throws {
        for v in vectors("valid") {
            let (h, payload) = try Packet.decode(hex(v[7]))
            #expect(h.type.rawValue == UInt8(v[2])!, "\(v[1])")
            #expect(h.seq == UInt32(v[3])!)
            #expect(h.streamId == UInt32(v[4])!)
            #expect(h.samplePos == UInt64(v[5])!)
            #expect(Array(payload) == hex(v[6]))
        }
    }

    @Test func invalidPacketsRejected() {
        let errors: [String: ProtocolError] = [
            "short": .short, "magic": .magic, "version": .version, "type": .type, "length": .length,
        ]
        for v in vectors("invalid") {
            #expect(throws: errors[v[2]]!, "\(v[1])") { try Packet.decode(hex(v[3])) }
        }
    }

    @Test func announceVectors() throws {
        for v in vectors("announce") {
            let a = Announce(sampleRate: UInt32(v[2])!, channels: UInt8(v[3])!, format: UInt8(v[4])!,
                             framesPerPacket: UInt16(v[5])!, nameBytes: hex(v[6]))
            #expect(a.encode() == hex(v[7]), "\(v[1])")
            #expect(try Announce.decode(hex(v[7])) == a)
        }
    }

    @Test func pcmVectors() {
        for v in vectors("pcm") {
            let samples = v[2].split(separator: ",").map { Int16($0)! }
            #expect(PCM.encode(samples) == hex(v[3]))
            #expect(PCM.decode(hex(v[3])) == samples)
        }
    }
}

@Suite struct ProtocolUnitTests {
    @Test func announceRoundTripThroughPacket() throws {
        let pkt = Packet.announce(Announce(name: "M4 Mic"), seq: 9)
        let (h, payload) = try Packet.decode(pkt)
        #expect(h.type == .announce && h.seq == 9)
        let a = try Announce.decode(payload)
        #expect(a.name == "M4 Mic")
        #expect(a.sampleRate == 48000 && a.channels == 1 && a.format == 1 && a.framesPerPacket == 240)
    }

    @Test func longNameTruncated() {
        let a = Announce(name: String(repeating: "x", count: 300))
        #expect(a.nameBytes.count == 255)
        #expect(a.encode().count == 9 + 255)
    }

    @Test func audioPacketSize() throws {
        let pkt = Packet.audio(seq: 1, streamId: 2, samplePos: 240, samples: [Int16](repeating: 5, count: 240))
        #expect(pkt.count == 24 + 480)
        let (h, payload) = try Packet.decode(pkt)
        #expect(h.samplePos == 240)
        #expect(PCM.decode(payload) == [Int16](repeating: 5, count: 240))
    }

    @Test func tokenParsing() {
        #expect(Token(hex: "") == .zero)
        #expect(Token(hex: "101112131415161718191A1B1C1D1E1F")?.bytes == Array(0x10...0x1F))
        #expect(Token(hex: "1011") == nil)
        #expect(Token(hex: "zz" + String(repeating: "0", count: 30)) == nil)
    }

    @Test func int16Saturation() {
        #expect(PCM.toInt16(0) == 0)
        #expect(PCM.toInt16(1.0) == 32767)
        #expect(PCM.toInt16(2.5) == 32767)
        #expect(PCM.toInt16(-1.0) == -32768)
        #expect(PCM.toInt16(-3) == -32768)
        #expect(PCM.toInt16(0.5) == 16384)
    }

    @Test func privateAddresses() {
        func ip(_ a: UInt32, _ b: UInt32, _ c: UInt32, _ d: UInt32) -> UInt32 { a << 24 | b << 16 | c << 8 | d }
        #expect(isPrivateIPv4(ip(10, 1, 2, 3)))
        #expect(isPrivateIPv4(ip(127, 0, 0, 1)))
        #expect(isPrivateIPv4(ip(172, 16, 0, 1)))
        #expect(isPrivateIPv4(ip(172, 31, 255, 255)))
        #expect(!isPrivateIPv4(ip(172, 32, 0, 1)))
        #expect(isPrivateIPv4(ip(192, 168, 1, 10)))
        #expect(isPrivateIPv4(ip(169, 254, 3, 4)))
        #expect(!isPrivateIPv4(ip(8, 8, 8, 8)))
        #expect(!isPrivateIPv4(ip(192, 169, 0, 1)))
    }
}
